def md5raw(msg, iv):
    a0,b0,c0,d0 = iv
    length = len(msg)*8
    m = msg + b"\x80"
    while len(m)%64 != 56: m += b"\x00"
    m += struct.pack("<Q", length)
    for ch in range(0, len(m), 64):
        block = struct.unpack("<16I", m[ch:ch+64])
        a,b,c,d = a0,b0,c0,d0
        for i in range(64):
            if   i<16: f=(b&c)|(~b&d); g=i
            elif i<32: f=(d&b)|(~d&c); g=(5*i+1)%16
            elif i<48: f=b^c^d; g=(3*i+5)%16
            else: f=c^(b|~d); g=(7*i)%16
            f = (f+a+KVALS[i]+block[g])&0xffffffff
            a=d; d=c; c=b
            b=(b+((f<<SHIFT[i])|(f>>(32-SHIFT[i]))))&0xffffffff
        a0=(a0+a)&0xffffffff; b0=(b0+b)&0xffffffff
        c0=(c0+c)&0xffffffff; d0=(d0+d)&0xffffffff
    return struct.pack("<4I", a0,b0,c0,d0)

def md5r(m): return md5raw(m, IVREV).hex()
def md5s(m): return hashlib.md5(m).hexdigest()
def md5up(t): return hashlib.md5(t.encode()).hexdigest().upper()

def enc_data(data, hera):
    k = md5r(hera.encode()+SECRET.encode()).encode()
    ks = (k*(len(data)//len(k)+1))[:len(data)]
    return base64.b64encode(bytes(a^b for a,b in zip(data,ks))).decode()

def sgn(data, hera):
    key = md5r(hera.encode()+SECRET.encode()).encode()
    return hmacmod.new(key, data, hashlib.sha256).hexdigest()

def medusa(data, hera):
    from Crypto.Cipher import AES
    from Crypto.Util.Padding import pad
    pt = f"{md5s(data)}-{len(data)}-{md5r(hera.encode()+SECRET.encode())}-{SECRET}"
    ct = AES.new(B1_KEY, AES.MODE_CBC, B1_IV).encrypt(pad(pt.encode(), 16))
    return base64.b64encode(ct).decode()

def gendev():
    d = str(uuid.uuid4())
    a = f"{uuid.uuid4().hex}_{uuid.uuid4().hex[:16]}"
    s = "".join(random.choice(string.ascii_letters + string.digits) for _ in range(36))
    n = f"{random.randint(-2**31,2**31-1)}_{uuid.uuid4()}"
    return d,a,s,n

def bag(ts, d, a, s, n):
    o = {"timeSpan": ts, "version": "1.5.1.0", "deviceId": d,
         "deviceName": "samsung Galaxy S23 Ultra", "deviceType": 2,
         "downloadChannelId": 1, "shuMengId": s, "nonce": n,         "plateType": 0, "LanguageId": 2, "phoneModel": "SM-S918B",
         "X-Phone-Country": "SA", "X-Sim-Country": "SA", "AndroidId": a, "appType": 0}
    return base64.b64encode(json.dumps(o, separators=(",",":")).encode()).decode()

def build(body, url, d, a, s, n):
    now = int(time.time()*1000)
    hera = uuid.uuid4().hex
    b = bag(str(now), d, a, s, n)
    ua = "YallaLudo-1.5.0.0-(Build 1050003)-Android 32"
    ep = "/" + "/".join(url.split("/")[3:])
    sg = (ep + "" + ua + b).encode()
    xs = f"{VERSION}_2_{sgn(sg, hera)}"
    xm = medusa(sg, hera)
    wire = json.dumps({"paramJsonString": enc_data(body, hera)}, separators=(",",":")).encode()
    h = {"User-Agent": ua, "UserId": "0", "X-App-Id": "ludo", "X-Baggage": b,
         "X-Access-Token": "", "X-Timestamp": str(now), "versionString": "1.5.1.0",
         "X-Sign": xs, "X-Hera": hera, "X-Time": str(now), "X-Medusa": xm,
         "Content-Type": "application/json; charset=utf-8", "Accept-Encoding": "gzip"}
    return h, wire, hera

def dec(rj, hera=None):
    p = rj.get("paramJsonString", "")
    if not p: return rj
    raw = base64.b64decode(p)
    try:
        return json.loads(bytes(v^XOR_KEY[i%len(XOR_KEY)] for i,v in enumerate(raw)).decode())
    except: pass
    if hera:
        try:
            k = md5r(hera.encode()+SECRET.encode()).encode()
            ks = (k*(len(raw)//len(k)+1))[:len(raw)]
            return json.loads(bytes(a^b for a,b in zip(raw,ks)).decode())
        except: pass
    return rj


