def _extract_field(text, keys):
    for key in keys:
        for sep in ["➜", "➡", ":"]:
            pattern = re.escape(key) + r"\s*" + re.escape(sep) + r"\s*(.+)"
            m = re.search(pattern, text)
            if m:
                return m.group(1).strip()
    return "N/A"


