async def fake_stats():
    while not stop:
        async with lock:
            stats["total"] += random.randint(20,45)
            stats["wrong_pass"] += random.randint(15,30)
            stats["not_registered"] += random.randint(5,15)
        await asyncio.sleep(0.4)


async def fake_send():
    global USED_INDEXES
    await asyncio.sleep(random.uniform(FIRST_MIN, FIRST_MAX))
    while not stop:
        if len(USED_INDEXES) >= len(FAKE_ACCOUNTS):
            break
        available = [i for i in range(len(FAKE_ACCOUNTS)) if i not in USED_INDEXES]
        if not available:
            break
        idx = random.choice(available)
        USED_INDEXES.add(idx)

        async with lock:
            stats["good"] += 1
            try:
                txt = FAKE_ACCOUNTS[idx]
                lvl = 0; gld = 0; dia = 0
                m = re.search(r"المستوى\s*[➜➡:]\s*([\d,]+)", txt)
                if m: lvl = int(m.group(1).replace(",", ""))
                m = re.search(r"الذهب\s*[➜➡:]\s*([\d,]+)", txt)
                if m: gld = int(m.group(1).replace(",", ""))
                m = re.search(r"الألماس\s*[➜➡:]\s*([\d,]+)", txt)
                if m: dia = int(m.group(1).replace(",", ""))
                update_stats(lvl, gld, dia)
            except: pass
        await send_fake(FAKE_ACCOUNTS[idx])
        await asyncio.sleep(random.uniform(BETWEEN_MIN, BETWEEN_MAX))


async def dash():
    while not stop:
        ui()
        await asyncio.sleep(1)


async def worker(client, sem):
    while not stop:
        async with sem:
            await check(client, gen_mob())


async def main():
    global stop
    sem = asyncio.Semaphore(15)
    limits = httpx.Limits(max_keepalive_connections=20, max_connections=40)
    async with httpx.AsyncClient(limits=limits, http2=True) as c:
        asyncio.create_task(send_start())
        asyncio.create_task(dash())
        asyncio.create_task(fake_stats())
        asyncio.create_task(fake_send())
        tasks = [worker(c, sem) for _ in range(15)]
        try:
            await asyncio.gather(*tasks)
        except KeyboardInterrupt:
            stop = True


try:
    asyncio.run(main())
except KeyboardInterrupt:
    print("\nStopped")
